ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2 ImageFileName=/\\(vssadmin|wmic|wbadmin|bcdedit|sc|net1?|taskkill)\.exe$/i NOT UserName=/\$$/
| case {
    ImageFileName=/vssadmin\.exe/i CommandLine=/delete\s+shadows/i | phase := "wipe";
    ImageFileName=/wmic\.exe/i CommandLine=/shadowcopy\s+delete/i | phase := "wipe";
    ImageFileName=/wbadmin\.exe/i CommandLine=/delete\s+(catalog|backup)/i | phase := "wipe";
    ImageFileName=/bcdedit\.exe/i CommandLine=/(recoveryenabled\s+no|bootstatuspolicy\s+ignoreallfailures)/i | phase := "wipe";
    ImageFileName=/(sc|net1?|taskkill)\.exe/i CommandLine=/(veeam|mssql|sqlserver|sqlwriter|sophos|sentinel|crowdstrike|mcafee|defender|msexchange|exchange|acronis|memtas|mepocs)/i | phase := "kill";
    * | phase := "other"
  }
| phase!="other"
| timechart(span=15m, series=phase, function=count(as=events), groupby=[aid, ComputerName, UserName])
| events > 0
| groupBy([aid, ComputerName, UserName, _bucket], function={ kill := sum(if(phase=="kill", events, 0)); wipe := sum(if(phase=="wipe", events, 0)) })
| kill >= 5 AND wipe >= 1
